#include <iostream>
#include <vector>
#include <map>
#include <set>

using namespace std;

struct Record {
    char type;
    int x;
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    if (!(cin >> n)) return 0;

    vector<Record> records(n);
    for (int i = 0; i < n; ++i) {
        cin >> records[i].type >> records[i].x;
    }

    set<int> friends;
    map<int, int> total_time;
    map<int, int> last_received;
    map<int, bool> waiting;

    int current_time = 0;
    bool has_previous_event = false;

    for (int i = 0; i < n; ++i) {
        if (records[i].type == 'T') {
            continue;
        }

        // Se há um evento anterior, calcula o tempo passado até este evento
        if (has_previous_event) {
            if (i > 0 && records[i - 1].type == 'T') {
                current_time += records[i - 1].x;
            } else {
                current_time += 1;
            }
        }

        has_previous_event = true;
        int friend_id = records[i].x;
        friends.insert(friend_id);

        if (records[i].type == 'R') {
            last_received[friend_id] = current_time;
            waiting[friend_id] = true;
        } else if (records[i].type == 'E') {
            total_time[friend_id] += (current_time - last_received[friend_id]);
            waiting[friend_id] = false;
        }
    }

    for (int friend_id : friends) {
        if (waiting[friend_id]) {
            cout << friend_id << " -1\n";
        } else {
            cout << friend_id << " " << total_time[friend_id] << "\n";
        }
    }

    return 0;
}
